"""Deterministic demo provider.

No model is called. Plans and edits are fixtures derived from the actual demo
repository contents; every resulting edit, test run and diff is real. This is
clearly reported to the UI and stored as a fixture execution.
"""

from __future__ import annotations

import json
from typing import Any

from app.agent.ai.base import AIProvider, AIResult, AIUsage, DemoFixtureError
from app.agent.context_builder import RepoContext

FIXTURE_NOTE = (
    "Generated by the deterministic AutoDev demo fixture provider. "
    "No AI model was called and no AI-generated code is present."
)


def _find_path(context: RepoContext, suffix: str) -> str:
    for path in context.files:
        if path.endswith(suffix):
            return path
    raise DemoFixtureError(
        f"The demo fixture expected a file ending with '{suffix}', but it is not in the "
        "repository context. Demo mode has fixtures only for the bundled calculator sample tasks; "
        "configure AI_API_KEY to analyze arbitrary repositories."
    )


def _ensure_imports(source: str, names: list[str], module: str = "calculator.operations") -> str:
    prefix = f"from {module} import "
    for line in source.splitlines():
        if line.startswith(prefix):
            existing = [part.strip() for part in line[len(prefix) :].split(",") if part.strip()]
            merged = existing + [name for name in names if name not in existing]
            return source.replace(line, prefix + ", ".join(merged), 1)
    marker = "from __future__ import annotations\n"
    import_line = prefix + ", ".join(names) + "\n"
    if marker in source:
        return source.replace(marker, marker + "\n" + import_line, 1)
    return import_line + "\n" + source


def _slugify(title: str) -> str:
    return "".join(ch.lower() if ch.isalnum() else "-" for ch in title).strip("-")[:40]


class DemoAIProvider(AIProvider):
    name = "demo-fixture"
    model = "deterministic-fixture"
    is_fixture = True

    async def _complete(self, messages: list[dict[str, str]], *, json_mode: bool = True) -> AIResult:
        # Demo provider never sends repository contents anywhere.
        return AIResult(
            content=json.dumps({"analysis": "demo fixture", "note": FIXTURE_NOTE}),
            provider=self.name,
            model=self.model,
            usage=AIUsage(),
            fixture=True,
        )

    def _target_files(self, context: RepoContext) -> tuple[str, str]:
        operations = _find_path(context, "calculator/operations.py")
        tests = _find_path(context, "tests/test_operations.py")
        return operations, tests

    def _is_multiply_task(self, title: str, description: str) -> bool:
        text = f"{title} {description}".lower()
        return "multiply" in text or "multiplication" in text

    def _is_clamp_task(self, title: str, description: str) -> bool:
        return "clamp" in f"{title} {description}".lower()

    async def analyze_task(
        self,
        *,
        task_title: str,
        task_description: str,
        repo_summary: dict[str, Any],
        context: RepoContext,
    ) -> AIResult:
        try:
            operations, tests = self._target_files(context)
        except DemoFixtureError:
            operations, tests = "(unknown)", "(unknown)"
        analysis = {
            "analysis": (
                f"The task '{task_title}' targets {operations}. The demo fixture inspects the "
                f"current implementation and its pytest suite at {tests}."
            ),
            "affected_areas": ["arithmetic operations", "test coverage"],
            "relevant_files": [operations, tests],
            "dependencies_to_respect": ["standard library only"],
            "existing_tests": [tests],
            "risks": ["Other arithmetic functions must keep working."],
            "provider_note": FIXTURE_NOTE,
        }
        return AIResult(
            content=json.dumps(analysis),
            provider=self.name,
            model=self.model,
            usage=AIUsage(),
            fixture=True,
        )

    async def generate_plan(
        self,
        *,
        task_title: str,
        task_description: str,
        repo_summary: dict[str, Any],
        context: RepoContext,
        analysis: str | None = None,
    ) -> AIResult:
        operations, tests = self._target_files(context)
        if self._is_multiply_task(task_title, task_description):
            plan = {
                "summary": (
                    "Fix multiply() so it returns the product of its arguments and add pytest "
                    "coverage for positive, negative and zero operands."
                ),
                "steps": [
                    {
                        "index": 1,
                        "title": "Inspect the multiply implementation",
                        "detail": f"Read {operations}.",
                    },
                    {
                        "index": 2,
                        "title": "Correct the arithmetic",
                        "detail": "Replace addition with multiplication inside multiply().",
                    },
                    {
                        "index": 3,
                        "title": "Add unit tests",
                        "detail": f"Extend {tests} with positive, negative and zero cases.",
                    },
                    {
                        "index": 4,
                        "title": "Run the pytest suite",
                        "detail": "Execute python -m pytest -q in the isolated workspace.",
                    },
                    {
                        "index": 5,
                        "title": "Review the diff",
                        "detail": "Confirm only the intended files changed and no secrets were added.",
                    },
                ],
                "files_likely_affected": [operations, tests],
                "test_plan": ["python -m pytest -q"],
                "risks": ["Changing add/subtract/divide behaviour accidentally."],
                "provider_note": FIXTURE_NOTE,
            }
        elif self._is_clamp_task(task_title, task_description):
            plan = {
                "summary": (
                    "Add a validated clamp(value, low, high) helper with inclusive bounds and "
                    "unit tests covering in-range, below-range, above-range and invalid bounds."
                ),
                "steps": [
                    {"index": 1, "title": "Inspect operations module", "detail": f"Read {operations}."},
                    {
                        "index": 2,
                        "title": "Implement clamp",
                        "detail": "Add a helper that raises ValueError when low > high.",
                    },
                    {
                        "index": 3,
                        "title": "Export the helper",
                        "detail": "Add clamp to the package __init__.",
                    },
                    {"index": 4, "title": "Add tests", "detail": f"Extend {tests} with clamp cases."},
                    {
                        "index": 5,
                        "title": "Run tests and review diff",
                        "detail": "Execute pytest and inspect the generated diff.",
                    },
                ],
                "files_likely_affected": [
                    operations,
                    _find_path(context, "calculator/__init__.py"),
                    tests,
                ],
                "test_plan": ["python -m pytest -q"],
                "risks": ["Invalid bounds handling must be consistent with the tests."],
                "provider_note": FIXTURE_NOTE,
            }
        else:
            raise DemoFixtureError(
                "Demo mode only ships fixtures for the two bundled calculator tasks "
                "('Fix the multiplication function...' and 'Add a clamp helper...'). "
                "Set AI_API_KEY and AI_PROVIDER=openai to work on arbitrary tasks."
            )
        return AIResult(
            content=json.dumps(plan),
            provider=self.name,
            model=self.model,
            usage=AIUsage(),
            fixture=True,
        )

    async def generate_changes(
        self,
        *,
        task_title: str,
        task_description: str,
        plan: dict[str, Any],
        repo_summary: dict[str, Any],
        context: RepoContext,
        previous_error: str | None = None,
    ) -> AIResult:
        operations, tests = self._target_files(context)
        ops_source = context.files[operations]
        tests_source = context.files[tests]
        edits: list[dict[str, Any]] = []

        if self._is_multiply_task(task_title, task_description):
            start = ops_source.find("def multiply(")
            if start == -1:
                raise DemoFixtureError("The multiply() function no longer exists in the demo repository")
            next_def = ops_source.find("\ndef ", start + 1)
            end = next_def if next_def != -1 else len(ops_source)
            block = ops_source[start:end]
            if "return a + b" not in block:
                raise DemoFixtureError(
                    "The demo fixture expected multiply() to contain 'return a + b'. "
                    "The fixture no longer matches this repository, so no edit was made."
                )
            new_block = block.replace("return a + b", "return a * b", 1)
            new_ops = ops_source[:start] + new_block + ops_source[end:]
            new_tests = _ensure_imports(tests_source, ["multiply"])
            if "def test_multiply_positive_numbers" not in new_tests:
                new_tests = (
                    new_tests.rstrip()
                    + """


def test_multiply_positive_numbers() -> None:
    assert multiply(6, 7) == 42


def test_multiply_negative_numbers() -> None:
    assert multiply(-4, 5) == -20


def test_multiply_by_zero() -> None:
    assert multiply(123, 0) == 0
"""
                )
            edits = [
                {
                    "path": operations,
                    "operation": "update",
                    "content": new_ops,
                    "reason": "multiply() returned a sum instead of a product",
                },
                {
                    "path": tests,
                    "operation": "update",
                    "content": new_tests,
                    "reason": "cover multiplication with unit tests",
                },
            ]
        elif self._is_clamp_task(task_title, task_description):
            new_ops = ops_source
            if "def clamp(" not in new_ops:
                new_ops = (
                    new_ops.rstrip()
                    + '''


def clamp(value: float, low: float, high: float) -> float:
    """Return value limited to the inclusive [low, high] range.

    Raises:
        ValueError: when low is greater than high.
    """
    if low > high:
        raise ValueError("low must be less than or equal to high")
    return max(low, min(value, high))
'''
                )
            init_path = _find_path(context, "calculator/__init__.py")
            new_init = context.files[init_path]
            if "clamp" not in new_init:
                new_init = new_init.replace(
                    "from .operations import add, divide, multiply, subtract",
                    "from .operations import add, clamp, divide, multiply, subtract",
                ).replace(
                    '"divide"]',
                    '"clamp", "divide"]',
                )
            new_tests = _ensure_imports(tests_source, ["clamp"])
            if "def test_clamp_within_range" not in new_tests:
                new_tests = (
                    new_tests.rstrip()
                    + """


def test_clamp_within_range() -> None:
    assert clamp(5, 0, 10) == 5


def test_clamp_below_range() -> None:
    assert clamp(-5, 0, 10) == 0


def test_clamp_above_range() -> None:
    assert clamp(50, 0, 10) == 10


def test_clamp_invalid_bounds() -> None:
    with pytest.raises(ValueError):
        clamp(5, 10, 0)
"""
                )
            edits = [
                {
                    "path": operations,
                    "operation": "update",
                    "content": new_ops,
                    "reason": "add clamp helper with validated bounds",
                },
                {
                    "path": init_path,
                    "operation": "update",
                    "content": new_init,
                    "reason": "export clamp from the package",
                },
                {
                    "path": tests,
                    "operation": "update",
                    "content": new_tests,
                    "reason": "cover clamp behaviour",
                },
            ]
        else:
            raise DemoFixtureError(
                "Demo mode only ships fixtures for the two bundled calculator tasks. "
                "Set AI_API_KEY to work on arbitrary tasks."
            )

        changeset = {
            "summary": f"Demo fixture changes for: {task_title}",
            "edits": edits,
            "notes": FIXTURE_NOTE,
        }
        return AIResult(
            content=json.dumps(changeset),
            provider=self.name,
            model=self.model,
            usage=AIUsage(),
            fixture=True,
        )

    async def analyze_failure(
        self,
        *,
        task_title: str,
        test_output: str,
        failing_tests: list[str],
        plan: dict[str, Any],
        context: RepoContext,
        attempt: int,
        max_attempts: int,
    ) -> AIResult:
        tail = "\n".join(test_output.strip().splitlines()[-15:])
        analysis = {
            "analysis": (
                "The demo fixture provider does not generate automatic corrections. "
                "The pytest output below must be reviewed by a human or by a live AI provider.\n\n"
                f"{tail}"
            ),
            "suspected_files": [],
            "changes": [],
            "manual_suggestions": [
                "Inspect the failing assertions in the test output.",
                "Run the suite locally in the execution workspace.",
                "Configure AI_API_KEY to enable AI-assisted failure analysis.",
            ],
        }
        return AIResult(
            content=json.dumps(analysis),
            provider=self.name,
            model=self.model,
            usage=AIUsage(),
            fixture=True,
        )

    async def summarize_changes(
        self,
        *,
        task_title: str,
        files: list[dict[str, Any]],
        tests: list[dict[str, Any]],
        validation: dict[str, Any],
        provider_note: str,
    ) -> AIResult:
        summary = {
            "summary": (
                f"Demo fixture execution for '{task_title}'. The change set was produced by a "
                "deterministic fixture (no AI model was called), applied to a real git workspace, "
                "and verified by the test commands listed in this pull request."
            ),
            "testing_notes": "See the test results section; values come from the sandbox.",
            "limitations": [
                "Demo fixture provider: deterministic edits, not AI-generated code.",
                "Requires human review before merge.",
            ],
        }
        return AIResult(
            content=json.dumps(summary),
            provider=self.name,
            model=self.model,
            usage=AIUsage(),
            fixture=True,
        )
